    return _default_cache


class CachedFunction:
    """Wrapper for cached functions."""
    def __init__(self, fn: Callable, cache: TTLCache) -> None:
        self.fn = fn
        self.cache = cache
        functools.update_wrapper(self, fn)

    def __call__(self, *args: Any, **kwargs: Any) -> Any:
        cache_key = str(args) + str(sorted(kwargs.items()))
        result = self.cache.get(cache_key)
        if result is not None:
            return result
        result = self.fn(*args, **kwargs)
        self.cache.set(cache_key, result)
        return result


def cached(ttl: int = 300) -> Callable[[Callable[..., Any]], CachedFunction]:
    """Decorator that caches function results based on arguments."""
    def decorator(fn: Callable[..., Any]) -> CachedFunction:
        cache = TTLCache(ttl_seconds=ttl)
