    *fns: Callable[[dict[str, Any]], dict[str, Any] | None]
) -> Callable[[dict[str, Any]], dict[str, Any] | None]:
    """Compose multiple transform functions into a single function."""
    def composed(data: dict[str, Any]) -> dict[str, Any] | None:
        current: dict[str, Any] | None = data
        for fn in fns:
            if current is None:
                return None
            current = fn(current)  # type: ignore[arg-type]
        return current
    return composed


