            result = fn(*args, **kwargs)
            elapsed = time.time() - start
            hist.observe(elapsed)
            return result
        # Copy metadata from original function
        wrapper.__name__ = fn.__name__
        wrapper.__doc__ = fn.__doc__
        return wrapper  # type: ignore[return-value]
    return decorator


